import{_ as s,o as a,c as e,a2 as n}from"./chunks/framework.B8LTMmvk.js";const c=JSON.parse('{"title":"Definitions and Conditional Compilation","description":"","frontmatter":{},"headers":[],"relativePath":"mlua/definitions.md","filePath":"mlua/definitions.md","lastUpdated":1789328014000}'),t={name:"mlua/definitions.md"};function l(d,i,h,p,o,r){return a(),e("div",null,[...i[0]||(i[0]=[n(`<h1 id="definitions-and-conditional-compilation" tabindex="-1">Definitions and Conditional Compilation <a class="header-anchor" href="#definitions-and-conditional-compilation" aria-label="Permalink to &quot;Definitions and Conditional Compilation&quot;">​</a></h1><p>Definitions are compile-time flags evaluated by MLua before your chunk is compiled. They let you easily turn features on or off, support different game versions, or separate debug code from release builds.</p><h2 id="declaring-values" tabindex="-1">Declaring Values <a class="header-anchor" href="#declaring-values" aria-label="Permalink to &quot;Declaring Values&quot;">​</a></h2><p>You can define flags right at the top of your Lua files using <code>#define</code>:</p><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">define SHOW_COUNTER </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">define LIMIT </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">define </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">MOD_NAME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;ExampleMod&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ifdef SHOW_COUNTER</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Counter feature is enabled!&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">endif</span></span></code></pre></div><p>Writing <code>#define NAME</code> by itself defines <code>NAME</code> as <code>true</code>. You can also assign booleans, numbers, or double-quoted strings. Note that directive names are case-sensitive.</p><h2 id="available-directives" tabindex="-1">Available Directives <a class="header-anchor" href="#available-directives" aria-label="Permalink to &quot;Available Directives&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Directive</th><th>What it does</th></tr></thead><tbody><tr><td><code>#define NAME value</code></td><td>Defines a flag or value in the active branch</td></tr><tr><td><code>#undef NAME</code></td><td>Removes a previously defined flag</td></tr><tr><td><code>#ifdef NAME</code></td><td>Checks if a flag has been defined</td></tr><tr><td><code>#ifndef NAME</code></td><td>Checks if a flag has not been defined</td></tr><tr><td><code>#if NAME</code></td><td>Checks if a definition evaluates to true</td></tr><tr><td><code>#ifnot NAME</code></td><td>Checks if a definition evaluates to false</td></tr><tr><td><code>#elif NAME</code>, <code>#elseif NAME</code></td><td>Alternative conditional branch</td></tr><tr><td><code>#else</code></td><td>Fallback branch if previous conditions were false</td></tr><tr><td><code>#endif</code>, <code>#end</code></td><td>Closes the conditional block</td></tr></tbody></table><p>Conditions take a flag name, optionally prefixed by <code>!</code> or <code>not</code>. This is a clean conditional compilation tool - arithmetic expressions like <code>#if VERSION &gt;= 2</code> are not supported.</p><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">define FEATURE </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ifdef FEATURE</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;FEATURE is defined&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">endif</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> FEATURE</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;This line will not be compiled&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#else</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;FEATURE is disabled&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">endif</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">undef FEATURE</span></span></code></pre></div><p>Lines inside inactive branches are simply skipped, preserving line numbering for accurate error messages.</p><h2 id="flags-provided-by-the-game" tabindex="-1">Flags Provided by the Game <a class="header-anchor" href="#flags-provided-by-the-game" aria-label="Permalink to &quot;Flags Provided by the Game&quot;">​</a></h2><p>Games can also inject global runtime flags into your environment through the <code>DEFINE</code> table. You can check for them using <code>defined(name)</code>:</p><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> defined</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;GAME_VERSION&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">then</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Running under game version:&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, DEFINE[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;GAME_VERSION&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">])</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">end</span></span></code></pre></div>`,14)])])}const E=s(t,[["render",l]]);export{c as __pageData,E as default};
